import 'package:flutter/material.dart';

import 'package:firebase_core/firebase_core.dart';

import 'core/alarm_service.dart';
import 'core/app_colors.dart';
import 'core/app_state.dart';
import 'core/auth_service.dart';
import 'core/notification_service.dart';
import 'core/settings_store.dart';
import 'core/widgets/alarm_banner.dart';
import 'features/auth/splash_page.dart';
// Generated by the `flutterfire configure` command (see setup steps).
import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // Saved settings and alarm limits (theme, language, sound, limits...).
  await SettingsStore.instance.load();
  await AlarmService.instance.loadLimits();
  await NotificationService.instance.init();

  // Already signed in (like Facebook)? The splash screen goes straight in.
  runApp(MyApp(signedIn: AuthService.isSignedIn));
}

class MyApp extends StatefulWidget {
  final bool signedIn;
  const MyApp({super.key, required this.signedIn});

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  @override
  void initState() {
    super.initState();
    darkMode.addListener(_themeChanged);
  }

  @override
  void dispose() {
    darkMode.removeListener(_themeChanged);
    super.dispose();
  }

  /// Colors come from [AppColors], so every widget must rebuild once.
  void _themeChanged() {
    setState(() {});
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      void visit(Element element) {
        element.markNeedsBuild();
        element.visitChildren(visit);
      }

      (context as Element).visitChildren(visit);
    });
  }

  @override
  Widget build(BuildContext context) {
    final dark = AppColors.dark;
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'ARGUS',
      theme: ThemeData(
        brightness: dark ? Brightness.dark : Brightness.light,
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFF54A9FF),
          brightness: dark ? Brightness.dark : Brightness.light,
        ),
        scaffoldBackgroundColor: AppColors.bg,
        fontFamily: 'Roboto',
        useMaterial3: true,
      ),
      // The alarm banner sits above every page.
      builder: (context, child) => MediaQuery(
        // Huge system font sizes broke the layouts: keep text near normal.
        data: MediaQuery.of(context).copyWith(
          textScaler: MediaQuery.of(context).textScaler.clamp(
            minScaleFactor: 0.9,
            maxScaleFactor: 1.1,
          ),
        ),
        child: Stack(
          fit: StackFit.expand,
          children: [
            child ?? const SizedBox.shrink(),
            const Positioned(top: 0, left: 0, right: 0, child: AlarmBanner()),
            const Positioned(
              bottom: 0,
              left: 0,
              right: 0,
              child: DeviceLostBanner(),
            ),
          ],
        ),
      ),
      home: SplashPage(signedIn: widget.signedIn),
    );
  }
}
